(* [comment removed for export] *)
Lemma depot_rep_miss : forall (D : depot) BK DNB SSB lo h sz SL SH (sid : word) (m m' : mem),
  depot_ok D DNB SSB lo -> depot_rep D BK DNB SSB m -> (0 <= h < 2^64)%Z -> (1 <= sz)%Z -> (d_tot D + sz + 1 < 2^20)%Z ->
  (lo <= SL)%Z ->
  munch [(d_tab + 4 * bkt h, d_tab + 4 * bkt h + 4); (d_nuniq, d_nuniq + 4);
         (DNB + 16 * (Z.of_nat (length (d_hs D)) + 1), DNB + 16 * (Z.of_nat (length (d_hs D)) + 1) + 16);
         (s_total, s_total + 8); (s_stored0, s_stored0 + 4); (SSB + 8 * d_tot D, SSB + 8 * (d_tot D + sz + 1)); (SL, SH)]%Z m m' ->
  wmono asegs m m' ->
  rw_cells asegs m' (d_tab + 4 * bkt h) [C4 (Z_to_bv 64 (Z.of_nat (length (d_hs D)) + 1))] ->
  rw_cells asegs m' d_nuniq [C4 (Z_to_bv 64 (Z.of_nat (length (d_hs D)) + 1))] ->
  rw_cells asegs m' d_map1 [C8 (Z_to_bv 64 DNB)] ->
  rw_cells asegs m' (DNB + 16 * (Z.of_nat (length (d_hs D)) + 1))
    [C8 (Z_to_bv 64 h); C4 (Z_to_bv 64 (tab_of (d_hs D) (bkt h))); C4 sid] ->
  stk asegs m' (DNB + 16 * (Z.of_nat (length (d_hs D)) + 1) + 16) (DNB + 2 ^ 20) ->
  rw_cells asegs m' s_total [C8 (Z_to_bv 64 (d_tot D + sz + 1))] -> rw_cells asegs m' s_data0 [C8 (Z_to_bv 64 SSB)] ->
  rw_cells asegs m' s_stored0 [C4 (Z_to_bv 64 (d_tot D + sz + 1))] ->
  stk asegs m' (SSB + 8 * (d_tot D + sz + 1)) (SSB + 2 ^ 23) ->
